<script>const manualBreakdownModal=document.getElementById('manualBreakdownModal');const breakdownToolbar=document.querySelector('.breakdown-head .breakdown-search');if(breakdownToolbar){const addButton=document.createElement('button');addButton.type='button';addButton.className='breakdown-btn breakdown-add-btn';addButton.textContent='+ Breakdown';addButton.addEventListener('click',()=>manualBreakdownModal.showModal());breakdownToolbar.before(addButton)}@if($errors->any())manualBreakdownModal.showModal();@endif document.querySelectorAll('.file-picker').forEach(picker=>{const input=picker.querySelector('input');const name=picker.querySelector('.file-picker-name');const setName=value=>{name.textContent=value;name.title=value};setName(name.textContent.trim());input.addEventListener('change',()=>{setName(input.files?.[0]?.name||'Belum ada file');name.style.color=input.files?.length?'#0f172a':'#64748b'})});</script>
