<script>if(breakdownToolbar){const addButton=breakdownToolbar.previousElementSibling;if(addButton?.classList.contains('breakdown-add-btn')){const actions=document.createElement('div');actions.className='breakdown-head-actions';breakdownToolbar.parentNode.insertBefore(actions,addButton);actions.append(addButton,breakdownToolbar)}}function replacePicWithSelect(name,items,placeholder,current){const input=manualBreakdownModal.querySelector(`[name="${name}"]`);if(!input)return;const select=document.createElement('select');select.name=name;select.required=input.required;const empty=document.createElement('option');empty.value='';empty.textContent=placeholder;select.appendChild(empty);items.forEach(item=>{const option=document.createElement('option');option.value=item.name;option.textContent=item.name;option.selected=item.name===current;select.appendChild(option)});input.replaceWith(select)}replacePicWithSelect('pic_engineering',@json($picsEngineering),'Pilih PIC Engineering',@json(old('pic_engineering')));replacePicWithSelect('pic_marketing',@json($picsMarketing),'Pilih PIC Marketing',@json(old('pic_marketing')));</script>
